fn main() {
    let mut scenarios: Vec<bool> = Vec::new();

    // Generate 200 synthetic memory safety scenarios
    for i in 0..200 {
        // Scenario: Create a vector, push an element, then use it
        let mut data = Vec::new();
        data.push(i);
        let len = data.len();
        scenarios.push(len > 0);
    }

    // Verify all scenarios passed (all vectors were non-empty)
    assert!(scenarios.iter().all(|&x| x));

    println!("Ownership test passed.");
}
